class CyberCloudClient:
    """The public REST API at api-version 2026-08-01.

    ⚠ Every method builds a path and hands it to the transport. Authentication, the api-version
    query parameter and correlation are the transport's; HttpTransport in _runtime is the
    standard-library one, and anything implementing Transport can replace it.
    """

    def __init__(self, transport: Transport) -> None:
        self._transport = transport
        self.operations = OperationsClient(transport)
        self.tenants = TenantsClient(transport)
        self.subscriptions = SubscriptionsClient(transport)
        self.resource_groups = ResourceGroupsClient(transport)
        self.analytics = AnalyticsProvider(transport)
        self.cache = CacheProvider(transport)
        self.communication = CommunicationProvider(transport)
        self.containerregistry = ContainerRegistryProvider(transport)
        self.containerservice = ContainerServiceProvider(transport)
        self.dbformysql = DBforMySQLProvider(transport)
        self.dbforpostgresql = DBforPostgreSQLProvider(transport)
        self.documentdb = DocumentDBProvider(transport)
        self.mail = MailProvider(transport)
        self.messaging = MessagingProvider(transport)
        self.monitor = MonitorProvider(transport)
        self.network = NetworkProvider(transport)
        self.sample = SampleProvider(transport)
        self.search = SearchProvider(transport)
        self.storage = StorageProvider(transport)
        self.terminal = TerminalProvider(transport)
